   631  void AddressResolver::SendAddressQueryResponse(const ThreadTargetTlv &             aTargetTlv,
   632                                                 const ThreadMeshLocalEidTlv &       aMlEidTlv,
   633                                                 const ThreadLastTransactionTimeTlv *aLastTransactionTimeTlv,
   634                                                 const Ip6::Address &                aDestination)
   635  {
   636      otError          error;
   637      Coap::Message *  message;
   638      ThreadRloc16Tlv  rloc16Tlv;
   639      Ip6::MessageInfo messageInfo;
   640
   641      VerifyOrExit((message = Get<Coap::Coap>().NewMessage()) != NULL, error = OT_ERROR_NO_BUFS);
   642
   643      message->Init(OT_COAP_TYPE_CONFIRMABLE, OT_COAP_CODE_POST);
   644      SuccessOrExit(error = message->AppendUriPathOptions(OT_URI_PATH_ADDRESS_NOTIFY));
   645      SuccessOrExit(error = message->SetPayloadMarker());
   646
   647      SuccessOrExit(error = message->AppendTlv(aTargetTlv));
   648      SuccessOrExit(error = message->AppendTlv(aMlEidTlv));
   649
   650      rloc16Tlv.Init();
   651      rloc16Tlv.SetRloc16(Get<Mle::MleRouter>().GetRloc16());
   652      SuccessOrExit(error = message->AppendTlv(rloc16Tlv));
   653
   654      if (aLastTransactionTimeTlv != NULL)
   655      {
   656          SuccessOrExit(error = message->AppendTlv(*aLastTransactionTimeTlv));
   657      }
   658
   659      messageInfo.SetPeerAddr(aDestination);
   660      messageInfo.SetSockAddr(Get<Mle::MleRouter>().GetMeshLocal16());
   661      messageInfo.SetPeerPort(kCoapUdpPort);
   662
   663      SuccessOrExit(error = Get<Coap::Coap>().SendMessage(*message, messageInfo));
   664
   665      otLogInfoArp("Sending address notification for target %s", aTargetTlv.GetTarget().ToString().AsCString());
   666
   667  exit:
   668
   669      if (error != OT_ERROR_NONE && message != NULL)
   670      {
   671          message->Free();
   672      }
   673  }
